{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C03","C10","C16","C01","C13","C12","C29","C04","C11","C02","C31","C40"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03","C10","C16"],
  "claims": [
    {
      "claim": "Cebranopadol, the closest measured structural context with a fused indole, aryl fluoride, and basic amine, has fasted absolute oral bioavailability of approximately 40%, above the 20% threshold despite substantial first-pass metabolism.",
      "card_ids": ["C03","C10"]
    },
    {
      "claim": "L3 exposure records confirm that oral cebranopadol reaches measurable plasma Cmax values of 71.1 to 89.7 pg/mL after 200 µg doses in fasted healthy subjects, consistent with its measured F of about 40%.",
      "card_ids": ["C31","C40"]
    },
    {
      "claim": "The fused fluorinated lactam analog (compound 6) was predicted to have high human bioavailability and showed 77-88% oral bioavailability in dog and monkey.",
      "card_ids": ["C16","C25","C27"]
    },
    {
      "claim": "Fasted-state absolute F measurements in humans for related small molecules are all above 20%: safinamide 95%, linezolid 93-100%, aprepitant 59-67%, and darolutamide 98.9% as an oral solution.",
      "card_ids": ["C01","C13","C12","C29","C04","C11","C02"]
    },
    {
      "claim": "The physicochemical prior (low neutral fraction, low logD) is not affirmative evidence for F below 20% and is outweighed by direct positive bioavailability records.",
      "card_ids": ["C03","C10","C16"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No query-specific IV reference or matched fasted-state PK study.",
    "L3 exposure records lack IV comparators, so they cannot quantify F for the query or for M01 and M02.",
    "Closest measured analog (cebranopadol) has substantial first-pass metabolism, so query first-pass cannot be excluded.",
    "No direct solubility, dissolution, or permeability data for the query; the prior is computational only.",
    "Darolutamide context has conflicting fasted F values (about 30% vs 98.9%), so formulation and dose dependence is unresolved."
  ],
  "decision_summary": "Predicted high: F >= 20% is better supported. All relevant L1 and L2 records report F above 20%, with the closest structural context (cebranopadol, fasted F about 40%) reinforced by L3 exposure records showing measurable oral plasma levels. Related fasted human drugs (safinamide 95%, linezolid 93-100%, aprepitant 59-67%, darolutamide 98.9% oral solution) are supportive. The mixed physicochemical prior does not affirmatively establish F below 20%. Confidence remains moderate because no direct query measurement exists and first-pass cannot be excluded."
}

